## 4️⃣ Full minimal example (ES-module build)

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>MapLibre – custom marker icon</title>
  <link href="https://unpkg.com/maplibre-gl@^6/dist/maplibre-gl.css" rel="stylesheet" />
  <style>
    #map { position: absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import * as maplibregl from 'https://unpkg.com/maplibre-gl@^6/dist/maplibre-gl.mjs';

  const map = new maplibregl.Map({
    container: 'map',
    style: 'https://tiles.openfreemap.org/styles/liberty', // any non-Mapbox style
    center: [-122.42, 37.78],
    zoom: 12
  });

  // Wait for the style to be ready
  map.on('load', async () => {
    try {
      const { data: img } = await map.loadImage(
        'https://raw.githubusercontent.com/maplibre/maplibre-gl-js/main/docs/assets/pin.png'
      );
      // Register the image under the name "pin"
      map.addImage('pin', img);

      // Add a layer that uses the image
      map.addLayer({
        id: 'my-pin',
        type: 'symbol',
        source: {
          type: 'geojson',
          data: {
            type: 'FeatureCollection',
            features: [{
              type: 'Feature',
              geometry: { type: 'Point', coordinates: [-122.42, 37.78] }
            }]
          }
        },
        layout: {
          'icon-image': 'pin',
          'icon-size': 0.5,
          'icon-allow-overlap': true
        }
      });
    } catch (e) {
      console.error('Could not load custom pin image', e);
    }
  });
</script>
</body>
</html>
```

*Run this snippet (or copy-paste into a local file) and you’ll see a custom pin icon on the map.*  

If you replace the `style` URL with your own style, just make sure the style’s `sprite` and `glyphs` URLs are also non-Mapbox (see the migration guide’s **Step 3**).

