## Full Minimal Example (ES-module build)

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>MapLibre – custom marker image</title>
  <link href="https://unpkg.com/maplibre-gl@^6.0.0/dist/maplibre-gl.css" rel="stylesheet" />
  <style>
    #map { position: absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import * as maplibregl from 'https://unpkg.com/maplibre-gl@^6.0.0/dist/maplibre-gl.mjs';

  const map = new maplibregl.Map({
    container: 'map',
    style: 'https://tiles.openfreemap.org/styles/liberty', // any non-Mapbox style
    center: [-122.42, 37.78],
    zoom: 12
  });

  map.on('load', async () => {
    try {
      const { data: img } = await map.loadImage(
        // replace with your own PNG URL (must be CORS-enabled)
        'https://raw.githubusercontent.com/maplibre/maplibre-gl-js/main/docs/assets/custom-marker.png'
      );

      // Register the image under the name "pin"
      map.addImage('pin', img);

      // Add a marker that uses the newly-added image
      new maplibregl.Marker({ element: createImgElement('pin') })
        .setLngLat([-122.42, 37.78])
        .addTo(map);
    } catch (e) {
      console.error('Could not load marker image:', e);
    }
  });

  // Helper: create a DOM element that uses the style-image we just added
  function createImgElement(imageName) {
    const el = document.createElement('div');
    el.style.backgroundImage = `url(${map.getStyle().sprite}/${imageName}.png)`;
    el.style.width = '32px';
    el.style.height = '32px';
    el.style.backgroundSize = 'contain';
    return el;
  }
</script>
</body>
</html>
```

> **Tip:** If you don’t need a custom DOM element and just want the style-image to appear in a *symbol layer*, you can skip the `Marker` entirely and add a layer like:

```javascript
map.addLayer({
  id: 'my-pins',
  type: 'symbol',
  source: {
    type: 'geojson',
    data: {
      type: 'FeatureCollection',
      features: [{ type: 'Feature', geometry: { type: 'Point', coordinates: [-122.42, 37.78] } }]
    }
  },
  layout: {
    'icon-image': 'pin',
    'icon-size': 1
  }
});
```

